CREATE TABLE IF NOT EXISTS file_versions(id UUID PRIMARY KEY,file_id UUID NOT NULL REFERENCES file_metadata(id) ON DELETE CASCADE,version_number INT NOT NULL,size_bytes BIGINT NOT NULL,content_hash VARCHAR(64) NOT NULL,created_at TIMESTAMPTZ NOT NULL,UNIQUE(file_id,version_number));
CREATE TABLE IF NOT EXISTS chunks(id UUID PRIMARY KEY,file_id UUID NOT NULL REFERENCES file_metadata(id) ON DELETE CASCADE,chunk_index INT NOT NULL,storage_node_id VARCHAR(255) NOT NULL,replica_node_ids TEXT[] NOT NULL DEFAULT '{}',checksum VARCHAR(64),uploaded BOOLEAN NOT NULL DEFAULT FALSE,plain_size INT NOT NULL DEFAULT 0,UNIQUE(file_id,chunk_index));CREATE INDEX IF NOT EXISTS idx_chunks_file ON chunks(file_id,chunk_index);
